function mapFingerprintValues(
  definitions: Readonly<Record<string, FingerprintDefinition>>
): Readonly<Record<string, string>> {
  const seenValues = new Set<string>();
  const mapped: Record<string, string> = {};
  // The corrected ceiling (2026-08-26) covers the full reviewed 1,065-key
  // TASK-551-01 receipt with headroom; exceeding it fails module validation.
  if (Object.keys(definitions).length > MAX_QUERY_FINGERPRINTS) {
    throw new Error(QUERY_FINGERPRINT_REGISTRY_ERROR_CODES.tooManyFingerprints);
  }
  for (const key of Object.keys(definitions)) {
    const definition = definitions[key]!;
    // Values are canonical today (value === key); any future duplicate value
    // or unreviewed key addition fails closed at module evaluation.
    if (seenValues.has(definition.value)) {
      throw new Error(QUERY_FINGERPRINT_REGISTRY_ERROR_CODES.duplicateValue);
    }
    seenValues.add(definition.value);
    mapped[key] = definition.value;
  }
  return Object.freeze(mapped);
}

export const TASK551_QUERY_FINGERPRINTS: Readonly<Record<string, string>> = mapFingerprintValues(
  TASK551_QUERY_FINGERPRINT_DEFINITIONS
);

export type QueryFingerprintKey = Extract<keyof typeof TASK551_QUERY_FINGERPRINTS, string>;
export type QueryFingerprint = (typeof TASK551_QUERY_FINGERPRINTS)[QueryFingerprintKey];

/** Stable digest over the closed key set; used by receipts and verification. */
export function computeQueryFingerprintRegistryDigest(): string {
  const canonical = Object.keys(TASK551_QUERY_FINGERPRINT_DEFINITIONS)
    .sort()
    .map(
      (key) =>
        `${key}->${TASK551_QUERY_FINGERPRINT_DEFINITIONS[key]!.normalizedQuerySha256.join(",")}`
    )
    .join("\n");
  return createHash("sha256").update(canonical).digest("hex");
}
